async function deleteCharacter(characterId){if(!confirm('이 캐릭터를 삭제할까요? 삭제한 캐릭터와 장비는 복구할 수 없습니다.'))return;try{const result=await request('/api/rpg/characters/delete',{characterId});lastRoster=result.characters;renderCharacterSlots(lastRoster)}catch(error){toast(error.message)}}
